-- Generated by build_setup.py. Only for an ALREADY installed 25-table workspace.
-- Keeps customers, predictions, cases, messages, approvals, outcomes and request keys.
-- Removes only the obsolete AI retry/lease metadata; running AI jobs become queued.
begin;
do $$ declare f record; begin
  if to_regclass('public.staff_members') is null then raise exception 'Use setup.sql for a new project'; end if;
  for f in select p.oid from pg_proc p where p.pronamespace='public'::regnamespace
    and p.proname in ('retention_claim_job','retention_fail_job','retention_complete_job','retention_worker_context','retention_request_recommendation','retention_pending_jobs') loop
    execute format('drop function %s',f.oid::regprocedure);
  end loop;
end $$;
alter table public.automation_jobs
  add column if not exists rewrite_instructions text check(length(rewrite_instructions)<=2000),
  add column if not exists rewrite_source_text text check(length(rewrite_source_text)<=10000);
drop index if exists public.jobs_worker_idx;
alter table public.automation_jobs drop constraint if exists automation_jobs_status_check;
update public.automation_jobs set status='queued' where status='running';
alter table public.automation_jobs
  drop column if exists attempt_count,
  drop column if exists next_attempt_at,
  drop column if exists lease_token,
  drop column if exists lease_until,
  drop column if exists error_code,
  add constraint automation_jobs_status_check check (status in ('queued','completed','failed','cancelled'));
create index jobs_worker_idx on public.automation_jobs(status,created_at);

create or replace function app_private.cancel_pending(p_case uuid, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.delivery_outbox o set status='cancelled', error_code=p_reason,
    lease_token=null, lease_until=null
    from public.messages m where m.id=o.message_id and m.case_id=p_case
      and o.status in ('queued','sending');
  update public.messages set delivery_status='cancelled', approval_status='draft'
    where case_id=p_case and delivery_status in ('queued','sending');
  update public.follow_up_tasks set status='cancelled' where case_id=p_case and status in ('pending','due')
    and (p_reason <> 'customer_replied' or task_type='no_reply');
end $$;

create or replace function public.retention_save_draft(p_case_id uuid, p_body text, p_request_key text,
  p_channel text default 'Zalo', p_message_id uuid default null,
  p_expected_revision integer default null, p_offer_id uuid default null,
  p_internal boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_actor uuid; v_case public.retention_cases; v_message public.messages;
  v_revision public.message_revisions; v_conv uuid; v_id uuid; v_rev integer;
begin
  select * into v_case from public.retention_cases where id=p_case_id for update;
  v_actor := app_private.require_staff(p_case_id);
  if v_case.case_status='closed' then raise exception 'Case is closed'; end if;
  if p_request_key is null or length(btrim(p_request_key))=0 then raise exception 'Request key required'; end if;
  if p_body is null or length(btrim(p_body)) not between 1 and 10000 then raise exception 'Invalid message body'; end if;
  select r.* into v_revision from public.message_revisions r
    join public.messages m on m.id=r.message_id where r.request_key=p_request_key and m.case_id=p_case_id;
  if found then
    if v_revision.body <> p_body or v_revision.offer_id is distinct from p_offer_id then
      raise exception 'Request key already used with different content'; end if;
    if not exists(select 1 from public.messages m join public.conversations cv on cv.id=m.conversation_id
      where m.id=v_revision.message_id and cv.selected_channel=p_channel and (m.direction='internal')=p_internal
        and (p_message_id is null or m.id=p_message_id)) then raise exception 'Request key metadata conflict'; end if;
    return jsonb_build_object('message_id',v_revision.message_id,'revision',v_revision.revision);
  end if;
  if p_message_id is null then
    insert into public.conversations(case_id,customer_id,selected_channel)
      values(p_case_id,v_case.customer_id,p_channel)
      on conflict(case_id,selected_channel) do update set selected_channel=excluded.selected_channel
      returning id into v_conv;
    insert into public.messages(case_id,conversation_id,sender_type,sender_user_id,direction,visibility)
      values(p_case_id,v_conv,'agent',v_actor,
        case when p_internal then 'internal' else 'outbound' end,
        case when p_internal then 'internal' else 'external' end) returning id into v_id;
    v_rev := 1;
  else
    select * into v_message from public.messages where id=p_message_id and case_id=p_case_id for update;
    if not found or v_message.direction='inbound' or v_message.sent_at is not null then raise exception 'Message cannot be edited'; end if;
    if v_message.current_revision is distinct from p_expected_revision then raise exception 'Revision conflict'; end if;
    if (v_message.direction='internal') <> p_internal then raise exception 'Message visibility cannot change'; end if;
    if not exists(select 1 from public.conversations where id=v_message.conversation_id and selected_channel=p_channel) then
      raise exception 'Create a new message to change channel'; end if;
    v_id:=p_message_id; v_rev:=v_message.current_revision+1;
    update public.delivery_outbox set status='cancelled',error_code='revision_changed',lease_token=null,lease_until=null
      where message_id=v_id and status in ('queued','sending');
    update public.messages set current_revision=v_rev,approval_status='draft',delivery_status='not_queued'
      where id=v_id;
  end if;
  insert into public.message_revisions(message_id,revision,body,content_hash,offer_id,created_by,request_key)
    values(v_id,v_rev,p_body,encode(sha256(convert_to(p_body,'UTF8')),'hex'),p_offer_id,v_actor,p_request_key);
  insert into public.interaction_events(case_id,message_id,event_type,actor_user_id,metadata)
    values(p_case_id,v_id,'message.drafted',v_actor,jsonb_build_object('revision',v_rev));
  return jsonb_build_object('message_id',v_id,'revision',v_rev);
end $$;

create or replace function public.retention_review_message(p_message_id uuid, p_revision integer,
  p_decision text, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_case public.retention_cases; v_m public.messages; v_r public.message_revisions;
  v_actor uuid; v_channel text; v_approval uuid; v_outbox uuid;
begin
  select case_id into v_case.id from public.messages where id=p_message_id;
  select * into v_case from public.retention_cases where id=v_case.id for update;
  v_actor:=app_private.require_staff(v_case.id);
  select * into v_m from public.messages where id=p_message_id for update;
  if v_m.direction <> 'outbound' or v_m.current_revision <> p_revision or v_m.sent_at is not null then
    raise exception 'Outbound current unsent revision required'; end if;
  if p_decision not in ('approved','rejected') or p_decision is null then raise exception 'Invalid decision'; end if;
  if v_m.delivery_status='sending' then raise exception 'Delivery in progress'; end if;
  select * into v_r from public.message_revisions where message_id=p_message_id and revision=p_revision;
  select selected_channel into v_channel from public.conversations where id=v_m.conversation_id and status='open';
  if v_channel is null then raise exception 'Conversation is closed'; end if;
  if p_decision='approved' then
    perform app_private.assert_contact(v_case.id,v_channel);
    perform app_private.assert_offer(v_case.customer_id,v_r.offer_id,v_actor);
    select id into v_outbox from public.delivery_outbox where message_id=p_message_id
      and revision=p_revision and channel=v_channel and status in ('queued','sent');
    if found then return jsonb_build_object('outbox_id',v_outbox,'status','already_queued'); end if;
  end if;
  insert into public.message_approvals(message_id,revision,content_hash,reviewer_id,decision,reason)
    values(p_message_id,p_revision,v_r.content_hash,v_actor,p_decision,p_reason) returning id into v_approval;
  if p_decision='rejected' then
    update public.delivery_outbox set status='cancelled',error_code='rejected'
      where message_id=p_message_id and status='queued';
    update public.messages set approval_status='rejected',delivery_status='not_queued' where id=p_message_id;
  else
    insert into public.delivery_outbox(message_id,revision,content_hash,approval_id,channel,idempotency_key)
      values(p_message_id,p_revision,v_r.content_hash,v_approval,v_channel,
        p_message_id::text||':'||p_revision||':'||v_channel)
      on conflict(message_id,revision,channel) do update set approval_id=excluded.approval_id,
        status='queued',next_attempt_at=now(),error_code=null,lease_token=null,lease_until=null,
        attempt_count=0 returning id into v_outbox;
    update public.messages set approval_status='approved',delivery_status='queued' where id=p_message_id;
  end if;
  insert into public.interaction_events(case_id,message_id,event_type,actor_user_id,metadata)
    values(v_case.id,p_message_id,'message.'||p_decision,v_actor,jsonb_build_object('revision',p_revision));
  return jsonb_build_object('approval_id',v_approval,'outbox_id',v_outbox,'decision',p_decision);
end $$;

create or replace function public.retention_request_recommendation(p_case_id uuid,p_request_key text,
  p_instructions text default null,p_source_text text default null) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_id uuid; v_old_case uuid; v_instructions text:=nullif(btrim(p_instructions),''); v_source text:=nullif(btrim(p_source_text),'');
begin
  perform 1 from public.retention_cases where id=p_case_id and case_status<>'closed' for update;
  if not found then raise exception 'Case closed'; end if;
  perform app_private.require_staff(p_case_id);
  if length(p_instructions)>2000 or length(p_source_text)>10000 then raise exception 'Rewrite instructions or source text too long'; end if;
  if v_source is not null and v_instructions is null then raise exception 'Rewrite instructions required'; end if;
  if v_instructions is not null and (split_part(p_request_key,':',1)<>'manual' or split_part(p_request_key,':',2) not in ('message','call_script')) then
    raise exception 'Rewrite is only supported for message or call script requests'; end if;
  insert into public.automation_jobs(case_id,job_type,request_key,rewrite_instructions,rewrite_source_text)
    values(p_case_id,'recommendation',p_request_key,v_instructions,v_source) on conflict(request_key) do nothing returning id into v_id;
  if v_id is null then
    select id,case_id into v_id,v_old_case from public.automation_jobs where request_key=p_request_key;
    if v_old_case<>p_case_id or not exists(select 1 from public.automation_jobs where id=v_id and rewrite_instructions is not distinct from v_instructions and rewrite_source_text is not distinct from v_source) then raise exception 'Request key conflict'; end if;
  end if;
  return v_id;
end $$;

create or replace function public.retention_pending_jobs(p_limit integer default 10,p_output text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
  perform app_private.require_worker();
  if p_limit is null or p_limit not between 1 and 100 then raise exception 'Invalid limit'; end if;
  if p_output is not null and p_output not in ('message','call_script','explanation') then raise exception 'Invalid output'; end if;
  return (select coalesce(jsonb_agg(to_jsonb(j) order by j.created_at,j.id),'[]') from (
    select j.* from public.automation_jobs j join public.retention_cases c on c.id=j.case_id
    where j.status='queued' and c.case_status<>'closed' and (p_output is null or split_part(j.request_key,':',2)=p_output) order by j.created_at,j.id limit p_limit) j);
end $$;

create or replace function public.retention_complete_job(p_job_id uuid,
  p_action text,p_rationale text,p_message_body text,p_generation_mode text,
  p_model_version text,p_prompt_version text,p_call_script text default null,
  p_missing_fields jsonb default '[]',p_offer_id uuid default null,
  p_prediction_context_id uuid default null,p_channel text default 'Zalo') returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_job public.automation_jobs; v_case public.retention_cases; v_rec uuid; v_conv uuid; v_message uuid; v_output text;
begin
  perform app_private.require_worker();
  select c.* into v_case from public.retention_cases c join public.automation_jobs j on j.case_id=c.id
    where j.id=p_job_id for update of c;
  select * into v_job from public.automation_jobs where id=p_job_id for update;
  if v_job.status='completed' then
    select id into v_rec from public.ai_recommendations where request_key=v_job.request_key;
    select id into v_message from public.messages where recommendation_id=v_rec;
    return jsonb_build_object('status','completed','recommendation_id',v_rec,'message_id',v_message,'revision',case when v_message is null then null else 1 end);
  end if;
  if v_job.id is null or v_job.status<>'queued' then raise exception 'Job is not pending'; end if;
  if v_case.case_status='closed' then raise exception 'Case closed'; end if;
  if p_prediction_context_id is not null and not exists(select 1 from public.prediction_contexts
    where id=p_prediction_context_id and prediction_id=v_case.prediction_id) then raise exception 'Context mismatch'; end if;
  if p_offer_id is not null and not exists(select 1 from public.customer_offer_eligibility e
    join public.offers o on o.id=e.offer_id where e.customer_id=v_case.customer_id and e.offer_id=p_offer_id
      and e.eligible and e.valid_until>now() and o.active and o.valid_from<=now() and o.valid_until>now()) then
    raise exception 'Offer unavailable or ineligible'; end if;
  v_output:=case when split_part(v_job.request_key,':',1)='manual' then split_part(v_job.request_key,':',2) else 'care_pack' end;
  if v_output='call_script' and nullif(btrim(p_call_script),'') is null then raise exception 'Call script required'; end if;
  if v_output in ('call_script','explanation') and p_message_body is not null then raise exception 'This request must not create an outbound message'; end if;
  if nullif(btrim(p_rationale),'') is null then raise exception 'Rationale required'; end if;
  insert into public.ai_recommendations(case_id,prediction_context_id,request_key,action,offer_id,
    rationale,call_script,missing_fields,generation_mode,model_version,prompt_version)
    values(v_case.id,p_prediction_context_id,v_job.request_key,p_action,p_offer_id,p_rationale,
      p_call_script,p_missing_fields,p_generation_mode,p_model_version,p_prompt_version) returning id into v_rec;
  if v_output not in ('call_script','explanation') then
  insert into public.conversations(case_id,customer_id,selected_channel) values(v_case.id,v_case.customer_id,p_channel)
    on conflict(case_id,selected_channel) do update set selected_channel=excluded.selected_channel returning id into v_conv;
  insert into public.messages(case_id,conversation_id,sender_type,direction,visibility,ai_generated,recommendation_id)
    values(v_case.id,v_conv,'ai','outbound','external',true,v_rec) returning id into v_message;
  insert into public.message_revisions(message_id,revision,body,content_hash,offer_id,request_key)
    values(v_message,1,p_message_body,encode(sha256(convert_to(p_message_body,'UTF8')),'hex'),p_offer_id,'job:'||v_job.id);
  end if;
  update public.automation_jobs set status='completed',completed_at=now() where id=v_job.id;
  insert into public.interaction_events(case_id,message_id,event_type,metadata)
    values(v_case.id,v_message,'recommendation.drafted',jsonb_build_object('recommendation_id',v_rec,'generation_mode',p_generation_mode));
  return jsonb_build_object('status','completed','recommendation_id',v_rec,'message_id',v_message,'revision',case when v_message is null then null else 1 end);
end $$;

create or replace function public.retention_fail_job(p_job_id uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
  perform app_private.require_worker();
  perform 1 from public.retention_cases c join public.automation_jobs j on j.case_id=c.id
    where j.id=p_job_id for update of c;
  if not found then raise exception 'Job not found'; end if;
  update public.automation_jobs set status='failed' where id=p_job_id and status='queued';
end $$;

create or replace function public.retention_schedule_reminder(p_case_id uuid,p_due_at timestamptz,p_request_key text) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_case public.retention_cases; v_id uuid;
begin
  select * into v_case from public.retention_cases where id=p_case_id for update;
  perform app_private.require_staff(p_case_id);
  if v_case.case_status='closed' or p_due_at is null or p_due_at<=now() then raise exception 'Future reminder for open case required'; end if;
  insert into public.follow_up_tasks(case_id,task_type,due_at,assigned_agent_id,idempotency_key)
    values(p_case_id,'manual_reminder',p_due_at,v_case.assigned_agent_id,p_request_key)
    on conflict(idempotency_key) do nothing returning id into v_id;
  if v_id is null then select id into v_id from public.follow_up_tasks where idempotency_key=p_request_key and case_id=p_case_id;
    if v_id is null then raise exception 'Request key conflict'; end if; end if;
  update public.retention_cases set due_at=(select min(due_at) from public.follow_up_tasks
    where case_id=p_case_id and status in ('pending','due')),updated_at=now() where id=p_case_id;
  return v_id;
end $$;

create or replace function public.retention_complete_task(p_task_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare v_case uuid;
begin
  select case_id into v_case from public.follow_up_tasks where id=p_task_id;
  perform 1 from public.retention_cases where id=v_case for update;
  perform app_private.require_staff(v_case);
  update public.follow_up_tasks set status='completed',completed_at=now() where id=p_task_id and status in ('pending','due');
end $$;

create or replace function public.retention_request_support(p_case_id uuid,p_body text,p_request_key text,
  p_preferred_contact_time text default null) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_id uuid; v_old public.support_requests;
begin
  perform 1 from public.retention_cases where id=p_case_id and case_status<>'closed' for update;
  if not found then raise exception 'Case closed'; end if;
  perform app_private.require_staff(p_case_id);
  insert into public.support_requests(case_id,requested_by,request_body,preferred_contact_time,idempotency_key)
    values(p_case_id,auth.uid(),p_body,p_preferred_contact_time,p_request_key)
    on conflict(idempotency_key) do nothing returning id into v_id;
  if v_id is null then select * into v_old from public.support_requests where idempotency_key=p_request_key;
    if v_old.case_id<>p_case_id or v_old.request_body<>p_body or v_old.preferred_contact_time is distinct from p_preferred_contact_time then
      raise exception 'Request key conflict'; end if; v_id:=v_old.id; end if;
  return v_id;
end $$;

create or replace function public.retention_update_case(p_case_id uuid,p_status text,p_contact_result text,
  p_close_reason text default null) returns void
language plpgsql security definer set search_path='' as $$
begin
  perform 1 from public.retention_cases where id=p_case_id for update;
  perform app_private.require_staff(p_case_id);
  update public.retention_cases set case_status=p_status,contact_result=p_contact_result,
    closed_at=case when p_status='closed' then coalesce(closed_at,now()) else null end,
    close_reason=case when p_status='closed' then p_close_reason else null end,updated_at=now() where id=p_case_id;
  if p_status='closed' then
    perform app_private.cancel_pending(p_case_id,'case_closed');
    update public.automation_jobs set status='cancelled' where case_id=p_case_id and status='queued';
    update public.support_requests set handoff_status='cancelled' where case_id=p_case_id and handoff_status='queued';
  end if;
  insert into public.interaction_events(case_id,event_type,actor_user_id,metadata)
    values(p_case_id,'case.updated',auth.uid(),jsonb_build_object('status',p_status,'contact_result',p_contact_result));
end $$;

create or replace function public.retention_record_outcome(p_case_id uuid,p_churned boolean,p_source text,
  p_is_simulated boolean,p_observed_at timestamptz default null,p_evidence_ref text default null,
  p_offer_accepted boolean default null) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_case public.retention_cases; v_end date; v_id uuid;
begin
  select * into v_case from public.retention_cases where id=p_case_id for update;
  perform app_private.require_staff(p_case_id);
  v_end:=(v_case.target_period_start+interval '1 month')::date-1;
  if not p_is_simulated and exists(select 1 from public.customers where id=v_case.customer_id and is_synthetic) then
    raise exception 'Synthetic customer requires simulated outcome flag'; end if;
  if p_churned is not null and (p_observed_at is null or p_evidence_ref is null or
    p_observed_at>now() or p_observed_at < ((v_end+1)::timestamp at time zone 'Asia/Ho_Chi_Minh')) then
    raise exception 'Observed outcome requires evidence after the complete target period'; end if;
  insert into public.retention_outcomes(case_id,window_start,window_end,churned,offer_accepted,
    observed_at,source,evidence_ref,is_simulated,recorded_by)
    values(p_case_id,v_case.target_period_start,v_end,p_churned,p_offer_accepted,p_observed_at,
      p_source,p_evidence_ref,p_is_simulated,auth.uid())
    on conflict(case_id,window_start,window_end) do update set churned=excluded.churned,
      offer_accepted=excluded.offer_accepted,observed_at=excluded.observed_at,source=excluded.source,
      evidence_ref=excluded.evidence_ref,is_simulated=excluded.is_simulated,recorded_by=auth.uid(),updated_at=now()
    returning id into v_id;
  insert into public.interaction_events(case_id,event_type,actor_user_id,metadata)
    values(p_case_id,'outcome.recorded',auth.uid(),jsonb_build_object('outcome_id',v_id,'churned',p_churned,'is_simulated',p_is_simulated));
  return v_id;
end $$;

create or replace function public.retention_record_cost(p_case_id uuid,p_amount numeric,p_currency text,
  p_cost_type text,p_source text,p_is_simulated boolean,p_request_key text) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_id uuid; v_old public.intervention_costs;
begin
  perform 1 from public.retention_cases where id=p_case_id for update;
  perform app_private.require_staff(p_case_id);
  if not p_is_simulated and exists(select 1 from public.retention_cases c join public.customers cu
    on cu.id=c.customer_id where c.id=p_case_id and cu.is_synthetic) then
    raise exception 'Synthetic customer requires simulated cost flag'; end if;
  insert into public.intervention_costs(case_id,amount,currency,cost_type,source,is_simulated,idempotency_key)
    values(p_case_id,p_amount,p_currency,p_cost_type,p_source,p_is_simulated,p_request_key)
    on conflict(idempotency_key) do nothing returning id into v_id;
  if v_id is null then select * into v_old from public.intervention_costs where idempotency_key=p_request_key;
    if v_old.case_id<>p_case_id or v_old.amount<>p_amount or v_old.currency<>p_currency
      or v_old.cost_type<>p_cost_type or v_old.source<>p_source or v_old.is_simulated<>p_is_simulated then
      raise exception 'Request key conflict'; end if; v_id:=v_old.id; end if;
  return v_id;
end $$;

create or replace function public.retention_portal_send(p_conversation_id uuid,p_body text,p_event_key text) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_customer uuid; v_conv public.conversations; v_id uuid; v_event uuid; v_old public.messages;
begin
  v_customer:=app_private.require_portal(p_conversation_id);
  select * into v_conv from public.conversations where id=p_conversation_id;
  perform 1 from public.retention_cases where id=v_conv.case_id for update;
  if v_conv.status<>'open' or exists(select 1 from public.retention_cases where id=v_conv.case_id and case_status='closed') then
    raise exception 'Conversation closed'; end if;
  if p_event_key is null or length(btrim(p_event_key))=0 then raise exception 'Event key required'; end if;
  select m.* into v_old from public.interaction_events e join public.messages m on m.id=e.message_id
    where e.channel=v_conv.selected_channel and e.provider_event_id='portal:'||p_event_key;
  if found then
    if v_old.conversation_id<>p_conversation_id or v_old.sender_user_id<>auth.uid()
      or not exists(select 1 from public.message_revisions where message_id=v_old.id and body=p_body) then
      raise exception 'Event key conflict'; end if;
    return v_old.id;
  end if;
  insert into public.messages(case_id,conversation_id,sender_type,sender_user_id,direction,visibility,approval_status,delivery_status)
    values(v_conv.case_id,p_conversation_id,'customer',auth.uid(),'inbound','external','not_required','received') returning id into v_id;
  insert into public.message_revisions(message_id,revision,body,content_hash,created_by,request_key)
    values(v_id,1,p_body,encode(sha256(convert_to(p_body,'UTF8')),'hex'),auth.uid(),'portal:'||p_event_key);
  insert into public.interaction_events(case_id,message_id,event_type,actor_user_id,channel,provider_event_id)
    values(v_conv.case_id,v_id,'message.received',auth.uid(),v_conv.selected_channel,'portal:'||p_event_key) returning id into v_event;
  perform app_private.cancel_pending(v_conv.case_id,'customer_replied');
  update public.automation_jobs set status='cancelled' where case_id=v_conv.case_id and status='queued';
  update public.retention_cases set case_status='in_progress',contact_result='contacted',updated_at=now() where id=v_conv.case_id;
  perform app_private.notify_case(v_conv.case_id,'new_message','New customer message','inbound:'||v_id,v_event);
  -- A reply notifies staff; another AI draft requires a staff request.
  return v_id;
end $$;

create or replace function public.retention_opt_out(p_conversation_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare v_customer uuid; v_conv public.conversations;
begin
  v_customer:=app_private.require_portal(p_conversation_id);
  select * into v_conv from public.conversations where id=p_conversation_id;
  perform 1 from public.retention_cases where id=v_conv.case_id for update;
  insert into public.contact_preferences(customer_id,channel,contact_allowed,opt_out_at,consent_basis,evidence_ref)
    values(v_customer,v_conv.selected_channel,false,now(),'customer_opt_out','portal:'||auth.uid())
    on conflict(customer_id,channel) do update set contact_allowed=false,opt_out_at=now(),
      consent_basis=excluded.consent_basis,evidence_ref=excluded.evidence_ref,updated_at=now();
  perform app_private.cancel_pending(v_conv.case_id,'opt_out');
  update public.automation_jobs set status='cancelled' where case_id=v_conv.case_id and status='queued';
  insert into public.interaction_events(case_id,event_type,actor_user_id,channel)
    values(v_conv.case_id,'contact.opted_out',auth.uid(),v_conv.selected_channel);
end $$;

create or replace function public.retention_set_demo_consent(p_customer_id uuid,p_channel text,
  p_allowed boolean,p_evidence_ref text) returns void
language plpgsql security definer set search_path='' as $$
declare v_case record;
begin
  perform app_private.require_worker();
  if p_evidence_ref is null or length(btrim(p_evidence_ref))=0 then raise exception 'Consent evidence required'; end if;
  if not exists(select 1 from public.customers where id=p_customer_id and is_synthetic) then raise exception 'Synthetic customer required'; end if;
  -- Lock every affected case first, using the same lock order as send/reply.
  for v_case in select id from public.retention_cases where customer_id=p_customer_id order by id for update loop
    if not p_allowed then perform app_private.cancel_pending(v_case.id,'consent_revoked'); end if;
  end loop;
  insert into public.contact_preferences(customer_id,channel,contact_allowed,opt_out_at,consent_basis,evidence_ref)
    values(p_customer_id,p_channel,p_allowed,case when p_allowed then null else now() end,'explicit_demo_configuration',p_evidence_ref)
    on conflict(customer_id,channel) do update set contact_allowed=excluded.contact_allowed,
      opt_out_at=excluded.opt_out_at,consent_basis=excluded.consent_basis,evidence_ref=excluded.evidence_ref,updated_at=now()
    where not excluded.contact_allowed;
end $$;

create or replace function public.retention_worker_context(p_job_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_job public.automation_jobs; v_case public.retention_cases; v_context jsonb;
begin
  perform app_private.require_worker();
  select * into v_job from public.automation_jobs where id=p_job_id and status='queued';
  if not found then raise exception 'Job is not pending'; end if;
  select * into v_case from public.retention_cases where id=v_job.case_id;
  select context into v_context from public.prediction_contexts where prediction_id=v_case.prediction_id order by created_at desc limit 1;
  -- Deliberately omit feature vectors, score, raw SHAP, labels and generator audit.
  -- Customer text is untrusted content, never an instruction to override policy.
  return jsonb_build_object('snapshot_date',(select snapshot_date from public.churn_predictions where id=v_case.prediction_id),'target_period_start',v_case.target_period_start,'requested_at',v_job.created_at,'current_time',now(),'rewrite_instructions',v_job.rewrite_instructions,'rewrite_source_text',v_job.rewrite_source_text,'case_id',v_case.id,'requested_output',case when split_part(v_job.request_key,':',1)='manual' then split_part(v_job.request_key,':',2) else 'care_pack' end,'language','English','requires_staff_review',true,
    'customer',(select jsonb_build_object('display_name',display_name,'plan_name',plan_name,
      'monthly_fee',monthly_fee,'currency',currency,'billing_mode',billing_mode,'tenure_months',tenure_months)
      from public.customers where id=v_case.customer_id),
    'driver_groups',coalesce((select jsonb_agg(jsonb_build_object('rank',d->'rank','group_name',d->'group_name',
      'evidence_status',d->'evidence_status','supports_customer_situation_claim',d->'supports_customer_situation_claim',
      'suggested_action',d->'suggested_action','facts',coalesce((select jsonb_agg(jsonb_build_object('label',f->'label',
        'value',f->'value','unit',f->'unit','missing',f->'missing','observation',f->'observation'))
        from jsonb_array_elements(d->'facts') f),'[]'))) from jsonb_array_elements(v_context->'drivers') d),'[]'),
    'eligible_offers',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'title',o.title,'description',o.description,
      'requires_supervisor',o.requires_supervisor)) from public.offers o join public.customer_offer_eligibility e on e.offer_id=o.id
      where e.customer_id=v_case.customer_id and e.eligible and e.valid_until>now()
        and o.active and o.valid_from<=now() and o.valid_until>now()),'[]'),
    'conversation',coalesce((select jsonb_agg(jsonb_build_object('direction',m.direction,'body',r.body,'created_at',m.created_at)
      order by m.created_at,m.id) from public.messages m join public.message_revisions r on r.message_id=m.id
        and r.revision=case when m.direction='outbound' then m.sent_revision else m.current_revision end
      where m.case_id=v_case.id and m.visibility='external' and
        (m.direction='inbound' or (m.direction='outbound' and m.delivery_status='sent'))),'[]'));
end $$;

-- Separate queues by requested output; defaults preserve existing callers.
drop function if exists public.retention_pending_jobs(integer);
create or replace function public.retention_pending_jobs(p_limit integer default 10,p_output text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 perform app_private.require_worker();
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'Invalid limit'; end if;
 if p_output is not null and p_output not in ('message','call_script','explanation') then raise exception 'Invalid output'; end if;
 return (select coalesce(jsonb_agg(to_jsonb(j) order by j.created_at,j.id),'[]') from (
 select j.* from public.automation_jobs j join public.retention_cases c on c.id=j.case_id
 where j.status='queued' and c.case_status<>'closed'
 and (p_output is null or split_part(j.request_key,':',2)=p_output)
 order by j.created_at,j.id limit p_limit) j);
end $$;
revoke all on function public.retention_pending_jobs(integer,text) from public,anon,authenticated;
grant execute on function public.retention_pending_jobs(integer,text) to service_role;

-- Only the reserved, provisioned demo account can switch synthetic recipients.
create or replace function app_private.can_demo_portal(p_conversation uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from auth.users a join public.customer_portal_users u on u.user_id=a.id and u.active
 where a.id=auth.uid() and a.email='customer@retention.example')
 and exists(select 1 from public.conversations cv
 join public.customers cu on cu.id=cv.customer_id
 join public.retention_cases c on c.id=cv.case_id
 where cv.id=p_conversation and cv.transport='mock' and cu.profile_source='synthetic_demo' and cu.is_synthetic
 and c.case_status in ('in_progress','waiting_customer')
 and exists(select 1 from public.messages m where m.conversation_id=cv.id
 and m.direction='outbound' and m.visibility='external' and m.delivery_status='sent'))
$$;
revoke all on function app_private.can_demo_portal(uuid) from public,anon;
create or replace function app_private.require_portal(p_conversation uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_customer uuid;
begin
 select cv.customer_id into v_customer from public.conversations cv
 where cv.id=p_conversation and (
 exists(select 1 from public.customer_portal_users u where u.customer_id=cv.customer_id and u.user_id=auth.uid() and u.active)
 or app_private.can_demo_portal(cv.id));
 if v_customer is null then raise exception 'Conversation access denied' using errcode='42501'; end if;
 return v_customer;
end $$;
create or replace function public.retention_portal_threads() returns jsonb
language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('conversation_id',cv.id,
 'channel',cv.selected_channel,'transport',cv.transport,'status',cv.status,
 'display_name',c.display_name) order by cv.created_at),'[]')
 from public.conversations cv join public.customers c on c.id=cv.customer_id
 where exists(select 1 from public.customer_portal_users u where u.customer_id=cv.customer_id and u.user_id=auth.uid() and u.active)
 or app_private.can_demo_portal(cv.id)
$$;
notify pgrst,'reload schema';

-- Prevent repeated UI requests and overlapping executions from repeating model calls.
alter table public.automation_jobs add column if not exists claimed_at timestamptz;
alter table public.ai_recommendations add column if not exists used_at timestamptz;
create or replace function public.retention_request_recommendation(p_case_id uuid,p_request_key text,
  p_instructions text default null,p_source_text text default null) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_id uuid; v_old_case uuid; v_instructions text:=nullif(btrim(p_instructions),''); v_source text:=nullif(btrim(p_source_text),'');
begin
  perform 1 from public.retention_cases where id=p_case_id and case_status<>'closed' for update;
  if not found then raise exception 'Case closed'; end if;
  perform app_private.require_staff(p_case_id);
  if length(p_instructions)>2000 or length(p_source_text)>10000 then raise exception 'Rewrite instructions or source text too long'; end if;
  if v_source is not null and v_instructions is null then raise exception 'Rewrite instructions required'; end if;
  if v_instructions is not null and (split_part(p_request_key,':',1)<>'manual' or split_part(p_request_key,':',2) not in ('message','call_script')) then
    raise exception 'Rewrite is only supported for message or call script requests'; end if;
  select id,case_id into v_id,v_old_case from public.automation_jobs where request_key=p_request_key;
  if found then
    if v_old_case<>p_case_id or not exists(select 1 from public.automation_jobs where id=v_id and rewrite_instructions is not distinct from v_instructions and rewrite_source_text is not distinct from v_source) then raise exception 'Request key conflict'; end if;
    return v_id;
  end if;
  update public.automation_jobs set status='failed',completed_at=now()
    where case_id=p_case_id and status='queued' and claimed_at<now()-interval '5 minutes';
  if split_part(p_request_key,':',1)='manual' then
    select id into v_id from public.automation_jobs where case_id=p_case_id
      and split_part(request_key,':',1)='manual' and split_part(request_key,':',2)=split_part(p_request_key,':',2)
      and (status='queued' or (status='completed' and completed_at>now()-interval '15 seconds'
        and rewrite_instructions is not distinct from v_instructions and rewrite_source_text is not distinct from v_source))
      order by created_at desc limit 1;
    if found then return v_id; end if;
  end if;
  insert into public.automation_jobs(case_id,job_type,request_key,rewrite_instructions,rewrite_source_text)
    values(p_case_id,'recommendation',p_request_key,v_instructions,v_source) returning id into v_id;
  return v_id;
end $$;

create or replace function public.retention_pending_jobs(p_limit integer default 10,p_output text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
  perform app_private.require_worker();
  if p_limit is null or p_limit not between 1 and 100 then raise exception 'Invalid limit'; end if;
  if p_output is not null and p_output not in ('message','call_script','explanation') then raise exception 'Invalid output'; end if;
  update public.automation_jobs set status='failed',completed_at=now() where status='queued' and claimed_at<now()-interval '5 minutes';
  return (select coalesce(jsonb_agg(to_jsonb(j) order by j.created_at,j.id),'[]') from (
    select j.* from public.automation_jobs j join public.retention_cases c on c.id=j.case_id
    where j.status='queued' and j.claimed_at is null and c.case_status<>'closed' and (p_output is null or split_part(j.request_key,':',2)=p_output) order by j.created_at,j.id limit p_limit) j);
end $$;

create or replace function public.retention_worker_context(p_job_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_job public.automation_jobs; v_case public.retention_cases; v_context jsonb;
begin
  perform app_private.require_worker();
  select * into v_job from public.automation_jobs where id=p_job_id and status='queued';
  if not found then raise exception 'Job is not pending'; end if;
  select * into v_case from public.retention_cases where id=v_job.case_id;
  select context into v_context from public.prediction_contexts where prediction_id=v_case.prediction_id order by created_at desc limit 1;
  -- Deliberately omit feature vectors, score, raw SHAP, labels and generator audit.
  -- Customer text is untrusted content, never an instruction to override policy.
  return jsonb_build_object('snapshot_date',(select snapshot_date from public.churn_predictions where id=v_case.prediction_id),'target_period_start',v_case.target_period_start,'requested_at',v_job.created_at,'current_time',now(),'rewrite_instructions',v_job.rewrite_instructions,'rewrite_source_text',v_job.rewrite_source_text,'case_id',v_case.id,'care_stage',v_case.case_status,'contact_result',v_case.contact_result,'requested_output',case when split_part(v_job.request_key,':',1)='manual' then split_part(v_job.request_key,':',2) else 'care_pack' end,'language','English','requires_staff_review',true,
    'customer',(select jsonb_build_object('display_name',display_name,'plan_name',plan_name,
      'monthly_fee',monthly_fee,'currency',currency,'billing_mode',billing_mode,'tenure_months',tenure_months)
      from public.customers where id=v_case.customer_id),
    'driver_groups',coalesce((select jsonb_agg(jsonb_build_object('rank',d->'rank','group_name',d->'group_name',
      'evidence_status',d->'evidence_status','supports_customer_situation_claim',d->'supports_customer_situation_claim',
      'suggested_action',d->'suggested_action','facts',coalesce((select jsonb_agg(jsonb_build_object('label',f->'label',
        'value',f->'value','unit',f->'unit','missing',f->'missing','observation',f->'observation'))
        from jsonb_array_elements(d->'facts') f),'[]'))) from jsonb_array_elements(v_context->'drivers') d),'[]'),
    'eligible_offers',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'title',o.title,'description',o.description,
      'requires_supervisor',o.requires_supervisor)) from public.offers o join public.customer_offer_eligibility e on e.offer_id=o.id
      where e.customer_id=v_case.customer_id and e.eligible and e.valid_until>now()
        and o.active and o.valid_from<=now() and o.valid_until>now()),'[]'),
    'conversation',coalesce((select jsonb_agg(jsonb_build_object('direction',m.direction,'body',r.body,'created_at',m.created_at,'sent_at',m.sent_at)
      order by coalesce(m.sent_at,m.created_at),m.id) from public.messages m join public.message_revisions r on r.message_id=m.id
        and r.revision=case when m.direction='outbound' then m.sent_revision else m.current_revision end
      where m.case_id=v_case.id and m.visibility='external' and
        (m.direction='inbound' or (m.direction='outbound' and m.delivery_status='sent'))),'[]'));
end $$;

create or replace function public.retention_claim_ai_request(p_job_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_job public.automation_jobs;
begin
 perform app_private.require_worker();
 perform 1 from public.retention_cases c join public.automation_jobs j on j.case_id=c.id
   where j.id=p_job_id and c.case_status<>'closed' for update of c;
 if not found then return '[]'::jsonb; end if;
 update public.automation_jobs set claimed_at=now() where id=p_job_id and status='queued' and claimed_at is null returning * into v_job;
 if not found then return '[]'::jsonb; end if;
 return jsonb_build_array(to_jsonb(v_job));
end $$;
revoke all on function public.retention_claim_ai_request(uuid) from public,anon,authenticated;
grant execute on function public.retention_claim_ai_request(uuid) to service_role;


create or replace function public.retention_mark_script_used(p_recommendation_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare v_case uuid;
begin
 select case_id into v_case from public.ai_recommendations where id=p_recommendation_id
   and request_key like 'manual:call_script:%' and call_script is not null;
 if not found then raise exception 'Call script not found'; end if;
 perform 1 from public.retention_cases where id=v_case for update;
 perform app_private.require_staff(v_case);
 update public.ai_recommendations set used_at=coalesce(used_at,now()) where id=p_recommendation_id;
end $$;
revoke all on function public.retention_mark_script_used(uuid) from public,anon,service_role;
grant execute on function public.retention_mark_script_used(uuid) to authenticated;

notify pgrst,'reload schema';

