  for f in select p.oid,p.proname from pg_proc p where p.pronamespace='public'::regnamespace
    and p.proname like 'retention\_%' escape '\' loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',f.oid::regprocedure);
    execute format('grant execute on function %s to %I',f.oid::regprocedure,
      case when f.proname in ('retention_claim_delivery','retention_deliver_mock','retention_fail_delivery',
        'retention_claim_ai_request','retention_pending_jobs','retention_complete_job','retention_fail_job','retention_worker_context','retention_process_followups',
        'retention_process_support','retention_ingest_prediction','retention_set_demo_consent')
        then 'service_role' else 'authenticated' end);
  end loop;
end $$;
